var sb = new System.Text.StringBuilder();
var garage = UnityEngine.Object.FindObjectOfType<VehicleGarage>();
if (garage == null) return "no garage";
for (int i = 0; i < garage.variants.Length; i++)
{
    var v = garage.variants[i];
    if (v.root == null) continue;
    v.root.SetActive(true);
    var bodyMeshes = new System.Collections.Generic.List<Transform>();
    foreach (Transform t in v.root.GetComponentsInChildren<Transform>())
        if (t.name.ToLowerInvariant().StartsWith("body_")) bodyMeshes.Add(t);
    float minZ = 9999f, maxZ = -9999f, maxY = -9999f;
    foreach (Transform t in bodyMeshes)
    {
        foreach (Renderer r in t.GetComponents<Renderer>())
        {
            var b = r.localBounds;
            var c = b.center; var e = b.extents;
            for (int k = 0; k < 8; k++)
            {
                Vector3 lp = new Vector3((k & 1) == 0 ? c.x - e.x : c.x + e.x, (k & 2) == 0 ? c.y - e.y : c.y + e.y, (k & 4) == 0 ? c.z - e.z : c.z + e.z);
                Vector3 world = r.transform.TransformPoint(lp);
                Vector3 carLocal = garage.transform.InverseTransformPoint(world);
                if (carLocal.z < minZ) minZ = carLocal.z;
                if (carLocal.z > maxZ) maxZ = carLocal.z;
                if (carLocal.y > maxY) maxY = carLocal.y;
            }
        }
    }
    sb.AppendLine(i + " " + garage.specIds[i] + " bodyMinZ=" + minZ.ToString("F2") + " bodyMaxZ=" + maxZ.ToString("F2") + " roofY=" + maxY.ToString("F2"));
    v.root.SetActive(i == garage.selected);
}
Debug.Log("PROBE4 " + sb.ToString().Replace("\r", "").Replace("\n", " | "));
return sb.ToString();
